#include <ctype.h>
#include <stdio.h>

int main(void)
{
    int ch;
    unsigned long letters = 0UL;
    unsigned long digits = 0UL;
    unsigned long spaces = 0UL;

    while ((ch = getchar()) != EOF) {
        if (isalpha((unsigned char)ch) != 0) {
            ++letters;
        }
        if (isdigit((unsigned char)ch) != 0) {
            ++digits;
        }
        if (isspace((unsigned char)ch) != 0) {
            ++spaces;
        }
    }

    if (ferror(stdin) != 0) {
        fputs("Input error.\n", stderr);
        return 1;
    }

    printf("letters=%lu digits=%lu spaces=%lu\n",
           letters, digits, spaces);
    return 0;
}

#include <ctype.h>
#include <stdio.h>

int main(void)
{
    const char input[] = "CodeSaathi 2026!";
    size_t i;

    for (i = 0U; input[i] != '\0'; ++i) {
        int converted = tolower((unsigned char)input[i]);
        putchar(converted);
    }
    putchar('\n');
    return 0;
}
